// Redirects `import ... from 'three'` at the stub during tests.
//
// In the browser the import map in index.html points three at the CDN build.
// Node has no import map, so without this the whole dependency graph fails to
// resolve the moment characters.js reaches voxel.js. Scoped to test runs by
// living in node_modules, which the game itself never loads.
export * from '../../test/three-stub.mjs';
import def from '../../test/three-stub.mjs';
export default def;